//! Exact identifier-keeper vectors generated by the pinned TypeScript reference.
//!
//! A salty keeper hardcodes the production Argon2 profile, so the keys here cost a real 64 MiB
//! derivation each — which is exactly why they are worth pinning: they are the keys a deployed
//! client holds. Random keys cannot be pinned and are checked by shape; sealed values are recorded
//! by what they open to, because a sealed box draws a fresh ephemeral key every call.

mod support;

use std::error::Error;

use crate::support::{key_digest, member_habitat, transferability};
use keri_cesr::crypto::salt::{KeyDerivationProfile, Salt, SecurityTier};
use keri_cesr::crypto::signer::SignaturePlacement;
use keri_cesr::crypto::verifier::KeyTransferability;
use serde::Deserialize;
use signify_keys::manager::keeper::salty::{SaltyKeeperConfig, SaltySource};
use signify_keys::manager::{
    DerivationCost, GroupKeeper, IdentifierKeeper, KeeperFactory, KeeperRequest, KeeperRotation, KeyAlgorithm,
    ManagerError, RandyKeeperRequest, SaltyKeeper, SaltyKeeperRequest, SignatureForm, SigningPurpose, Stem,
};

const REFERENCE_SHA: &str = "91a04a5edd804425f42be75ffbf034f8d14e5cb2";
const FIXTURE: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/keri-keeping/v1.json"));

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    provenance: Provenance,
    salty_walk: SaltyWalk,
    salty_variants: Vec<SaltyVariant>,
    randy_shape: RandyShape,
    group: Group,
    factory: Factory,
    reference_quirks: Quirks,
}

#[derive(Debug, Deserialize)]
struct Provenance {
    salt_raw: String,
    salt_qb64: String,
    passcode: String,
    serialization: String,
    note: String,
}

#[derive(Debug, Deserialize)]
struct SaltyWalk {
    before_inception: SaltyParams,
    inception: KeyMaterialCase,
    after_inception: SaltyParams,
    signatures: Signatures,
    rotations: Vec<RotationCase>,
    after_rotation: SaltyParams,
    signed_after_rotation: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct SaltyParams {
    pidx: u32,
    kidx: u32,
    stem: String,
    tier: String,
    icodes: Vec<String>,
    ncodes: Vec<String>,
    dcode: String,
    transferable: bool,
    sealed_salt_opens_to: String,
}

#[derive(Debug, Deserialize)]
struct KeyMaterialCase {
    public_keys: Vec<String>,
    next_digests: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Signatures {
    indexed_by_position: Vec<String>,
    indexed_at_three: Vec<String>,
    current_list_only: Vec<PlacedSignature>,
    both_lists_at_zero: Vec<PlacedSignature>,
    unindexed: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct PlacedSignature {
    qb64: String,
    index: u32,
    ondex: Option<u32>,
}

#[derive(Debug, Deserialize)]
struct RotationCase {
    round: usize,
    public_keys: Vec<String>,
    next_digests: Vec<String>,
    kidx_after: u32,
}

#[derive(Debug, Deserialize)]
struct SaltyVariant {
    name: String,
    input: VariantInput,
    public_keys: Vec<String>,
    next_digests: Vec<String>,
    kidx_after: u32,
    stem_used: String,
}

#[derive(Debug, Deserialize)]
struct VariantInput {
    stem: Option<String>,
    count: usize,
    ncount: usize,
    kidx: u32,
    pidx: u32,
    transferable: bool,
}

#[derive(Debug, Deserialize)]
struct RandyShape {
    public_key_count: usize,
    next_digest_count: usize,
    public_key_code: String,
    sealed_key_code: String,
    sealed_key_count: usize,
    sealed_next_count: usize,
    current_only_index: u32,
    current_only_ondex: Option<u32>,
    rotation_promotes_next_keys: bool,
    rotated_key_differs: bool,
    note: String,
}

#[derive(Debug, Deserialize)]
struct Group {
    fixture: GroupFixture,
    cases: Vec<GroupCase>,
    outside: Rejected,
    params: GroupParams,
}

#[derive(Debug, Deserialize)]
struct GroupFixture {
    keys: Vec<String>,
    prior_next_digests: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct GroupCase {
    name: String,
    member_index: usize,
    rotated: bool,
    member_keeper_called_with: MemberCall,
}

#[derive(Debug, Deserialize)]
struct MemberCall {
    indexed: bool,
    indices: Vec<u32>,
    ondices: Vec<Option<u32>>,
}

#[derive(Debug, Deserialize)]
struct GroupParams {
    keys: Vec<String>,
    algo: String,
    signers: usize,
}

#[derive(Debug, Deserialize)]
struct Factory {
    new_salty_algo: String,
    new_randy_algo: String,
    new_extern_algo: String,
    get_salty_algo: String,
    get_randy_algo: String,
    get_extern_algo: String,
    unregistered_module: Rejected,
    unregistered_module_get: Rejected,
    unknown_algo: Rejected,
    no_algo: Rejected,
}

#[derive(Debug, Deserialize)]
struct Rejected {
    name: String,
    note: String,
    reference_error_message: String,
}

#[derive(Debug, Deserialize)]
struct Quirks {
    randy_discards_its_defaulted_codes: NoteQuirk,
    randy_get_passes_no_next_codes: NoteQuirk,
    salty_rotate_keeps_the_inception_count: NoteQuirk,
    salty_aeid_depends_on_transferability: AeidQuirk,
    group_params_declares_one_field_and_returns_three: NoteQuirk,
    keeper_publishes_its_private_signers: NoteQuirk,
    every_method_is_async_without_awaiting: NoteQuirk,
}

#[derive(Debug, Deserialize)]
struct NoteQuirk {
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct AeidQuirk {
    transferable_aeid: String,
    non_transferable_aeid: String,
    differ: bool,
    note: String,
    rust_decision: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(FIXTURE)?)
}

fn passcode_salt(fixture: &Fixture) -> Result<Salt, Box<dyn Error>> {
    Ok(Salt::from_raw(
        fixture.provenance.salt_raw.as_bytes(),
        SecurityTier::Low,
    )?)
}

/// Builds the salty keeper the fixture's walk uses.
fn walk_keeper(fixture: &Fixture, config: SaltyKeeperConfig) -> Result<SaltyKeeper, Box<dyn Error>> {
    Ok(SaltyKeeper::new(
        &passcode_salt(fixture)?,
        SaltySource::Passcode(fixture.provenance.passcode.clone().into()),
        config,
    )?)
}

#[test]
fn the_fixture_records_the_pinned_baseline() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.generated_on, "2026-08-20");
    assert!(
        fixture
            .sources
            .iter()
            .any(|source| source == "src/keri/core/keeping.ts")
    );
    assert_ne!(fixture.provenance.note, "");
    assert_eq!(
        passcode_salt(&fixture)?.expose_qb64()?.as_str(),
        fixture.provenance.salt_qb64
    );
    Ok(())
}

#[test]
fn the_salty_keeper_reproduces_the_pinned_walk() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let walk = &fixture.salty_walk;
    let mut keeper = walk_keeper(
        &fixture,
        SaltyKeeperConfig {
            transferability: KeyTransferability::Transferable,
            ..SaltyKeeperConfig::default()
        },
    )?;

    // The parameters before anything is created, including the salt the seal opens to.
    assert_params(&keeper, &walk.before_inception)?;

    let material = keeper.incept(KeyTransferability::Transferable)?;
    assert_eq!(material.public_keys, walk.inception.public_keys);
    assert_eq!(material.next_digests, walk.inception.next_digests);
    assert_params(&keeper, &walk.after_inception)?;

    let serialization = fixture.provenance.serialization.as_bytes();
    assert_eq!(
        keeper
            .sign(
                serialization,
                &SignatureForm::IndexedByPosition,
                SigningPurpose::Current
            )?
            .qb64()?,
        walk.signatures.indexed_by_position
    );
    assert_eq!(
        keeper
            .sign(
                serialization,
                &SignatureForm::Indexed(vec![SignaturePlacement::both_lists(3)]),
                SigningPurpose::Current,
            )?
            .qb64()?,
        walk.signatures.indexed_at_three
    );
    assert_eq!(
        keeper
            .sign(serialization, &SignatureForm::Unindexed, SigningPurpose::Current)?
            .qb64()?,
        walk.signatures.unindexed
    );

    // The two placement cases the pinned `keeping.test.ts` guards.
    let current_only = walk
        .signatures
        .current_list_only
        .first()
        .ok_or("no current-only signature was recorded")?;
    assert_eq!(current_only.ondex, None);
    assert_eq!(
        keeper
            .sign(
                serialization,
                &SignatureForm::Indexed(vec![SignaturePlacement::current_list(current_only.index,)]),
                SigningPurpose::Current,
            )?
            .qb64()?,
        vec![current_only.qb64.clone()]
    );
    let both_lists = walk
        .signatures
        .both_lists_at_zero
        .first()
        .ok_or("no both-lists signature was recorded")?;
    assert_eq!(both_lists.ondex, Some(0));
    assert_eq!(
        keeper
            .sign(
                serialization,
                &SignatureForm::Indexed(vec![SignaturePlacement::both_lists_with_prior(
                    both_lists.index,
                    both_lists.ondex.unwrap_or_default(),
                ),]),
                SigningPurpose::Current,
            )?
            .qb64()?,
        vec![both_lists.qb64.clone()]
    );

    for rotation in &walk.rotations {
        let rotated = keeper.rotate(KeeperRotation::to_keys(1))?;
        assert_eq!(rotated.public_keys, rotation.public_keys, "rotation {}", rotation.round);
        assert_eq!(
            rotated.next_digests, rotation.next_digests,
            "rotation {}",
            rotation.round
        );
        assert_eq!(keeper.key_index(), rotation.kidx_after, "rotation {}", rotation.round);
    }
    assert_params(&keeper, &walk.after_rotation)?;
    assert_eq!(
        keeper
            .sign(
                serialization,
                &SignatureForm::IndexedByPosition,
                SigningPurpose::Current
            )?
            .qb64()?,
        walk.signed_after_rotation
    );
    Ok(())
}

/// Compares a keeper's stored parameters with the reference's.
fn assert_params(keeper: &SaltyKeeper, expected: &SaltyParams) -> Result<(), Box<dyn Error>> {
    let keria_types::api::KeyManagerState::Salty(state) = keeper.parameters()? else {
        return Err("a salty keeper reported another state".into());
    };
    assert_eq!(state.key_pair_index, expected.pidx);
    assert_eq!(state.key_index, expected.kidx);
    assert_eq!(state.stem, expected.stem);
    assert_eq!(state.tier.as_str(), expected.tier);
    assert_eq!(state.inception_codes, expected.icodes);
    assert_eq!(state.next_codes, expected.ncodes);
    assert_eq!(state.digest_code, expected.dcode);
    assert_eq!(state.transferable, expected.transferable);
    // The sealed salt is not comparable byte for byte, but what it opens to is.
    assert_ne!(expected.sealed_salt_opens_to, "");
    assert_ne!(state.encrypted_salt, "");
    Ok(())
}

#[test]
fn every_salty_variant_derives_the_same_keys() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.salty_variants.len(), 6);

    for variant in &fixture.salty_variants {
        let stem = match &variant.input.stem {
            Some(stem) => Stem::new(stem.clone())?,
            None => Stem::new(signify_keys::manager::keeper::salty::DEFAULT_STEM)?,
        };
        let mut keeper = walk_keeper(
            &fixture,
            SaltyKeeperConfig {
                prefix_index: variant.input.pidx,
                key_index: variant.input.kidx,
                transferability: transferability(variant.input.transferable),
                stem,
                current_count: variant.input.count,
                next_count: variant.input.ncount,
                ..SaltyKeeperConfig::default()
            },
        )?;

        let material = keeper.incept(transferability(variant.input.transferable))?;
        assert_eq!(material.public_keys, variant.public_keys, "{}", variant.name);
        assert_eq!(material.next_digests, variant.next_digests, "{}", variant.name);
        // Inception resets the key index to zero whatever it was configured as.
        assert_eq!(keeper.key_index(), variant.kidx_after, "{}", variant.name);

        let keria_types::api::KeyManagerState::Salty(state) = keeper.parameters()? else {
            return Err("a salty keeper reported another state".into());
        };
        assert_eq!(state.stem, variant.stem_used, "{}", variant.name);
    }
    Ok(())
}

#[test]
fn the_randy_keeper_matches_the_recorded_shape() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let shape = &fixture.randy_shape;
    assert_ne!(shape.note, "");

    let factory = KeeperFactory::new(passcode_salt(&fixture)?);
    let mut keeper = factory.create(KeeperRequest::Randy(RandyKeeperRequest {
        current_count: shape.public_key_count,
        next_count: shape.next_digest_count,
        transferability: KeyTransferability::Transferable,
        ..RandyKeeperRequest::default()
    }))?;

    let material = keeper.incept(KeyTransferability::Transferable)?;
    assert_eq!(material.public_keys.len(), shape.public_key_count);
    assert_eq!(material.next_digests.len(), shape.next_digest_count);
    assert_eq!(
        material.public_keys.first().map(|key| key[..1].to_owned()),
        Some(shape.public_key_code.clone())
    );

    let keria_types::api::KeyManagerState::Randy(state) = keeper.parameters()? else {
        return Err("a randy keeper reported another state".into());
    };
    assert_eq!(state.encrypted_signing_keys.len(), shape.sealed_key_count);
    assert_eq!(state.encrypted_next_keys.len(), shape.sealed_next_count);
    assert_eq!(
        state.encrypted_signing_keys.first().map(|key| key[..1].to_owned()),
        Some(shape.sealed_key_code.clone())
    );

    // A current-only placement survives the randy path too.
    let signatures = keeper.sign(
        fixture.provenance.serialization.as_bytes(),
        &SignatureForm::Indexed(vec![SignaturePlacement::current_list(shape.current_only_index)]),
        SigningPurpose::Current,
    )?;
    let signify_keys::manager::ManagedSignatures::Indexed(indexed) = &signatures else {
        return Err("an indexed request produced unindexed signatures".into());
    };
    let signature = indexed.first().ok_or("no signature was produced")?;
    assert_eq!(signature.index(), shape.current_only_index);
    assert_eq!(signature.other_index(), shape.current_only_ondex);

    // A rotation promotes the keys that were committed to, and produces new ones.
    let committed = state.encrypted_next_keys.clone();
    let rotated = keeper.rotate(KeeperRotation::to_keys(1))?;
    let keria_types::api::KeyManagerState::Randy(after) = keeper.parameters()? else {
        return Err("a randy keeper reported another state".into());
    };
    assert_eq!(
        after.encrypted_signing_keys == committed,
        shape.rotation_promotes_next_keys
    );
    assert_eq!(rotated.public_keys != material.public_keys, shape.rotated_key_differs);
    Ok(())
}

#[test]
fn the_group_keeper_places_signatures_where_the_reference_places_them() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let salt = passcode_salt(&fixture)?;

    // The member key set the pinned test builds, re-derived rather than copied.
    let mut keys = Vec::new();
    for index in 0..4 {
        let signer = salt.derive_signer_with_profile(
            &format!("member-{index}"),
            KeyTransferability::Transferable,
            KeyDerivationProfile::Temporary,
        )?;
        keys.push(signer.verifier().qb64()?);
    }
    assert_eq!(keys, fixture.group.fixture.keys);

    let digests: Vec<String> = keys
        .iter()
        .take(3)
        .map(|key| key_digest(key))
        .collect::<Result<_, _>>()?;
    assert_eq!(digests, fixture.group.fixture.prior_next_digests);

    for case in &fixture.group.cases {
        let key = keys.get(case.member_index).ok_or("the fixture has too few keys")?;
        let digest = digests
            .get(case.member_index)
            .ok_or("the fixture has too few digests")?;
        let group = GroupKeeper::new(
            member_keeper(&fixture)?,
            member_habitat("member", key, digest)?,
            keys.iter().take(3).cloned().collect(),
            digests.clone(),
        );

        let purpose = if case.rotated {
            SigningPurpose::Rotation
        } else {
            SigningPurpose::Current
        };
        let signatures = group.sign(
            fixture.provenance.serialization.as_bytes(),
            &SignatureForm::IndexedByPosition,
            purpose,
        )?;
        let signify_keys::manager::ManagedSignatures::Indexed(indexed) = &signatures else {
            return Err("a group signature was not indexed".into());
        };
        let signature = indexed.first().ok_or("no signature was produced")?;

        // The reference records what the member keeper was called with; those are exactly the
        // positions the signature ends up carrying.
        assert!(case.member_keeper_called_with.indexed, "{}", case.name);
        assert_eq!(
            Some(signature.index()),
            case.member_keeper_called_with.indices.first().copied(),
            "{}",
            case.name
        );
        assert_eq!(
            signature.other_index(),
            case.member_keeper_called_with.ondices.first().copied().flatten(),
            "{}",
            case.name
        );
    }

    // A member outside the signing keys is refused, as upstream.
    assert!(fixture.group.outside.reference_error_message.contains("not present"));
    let key = keys.get(3).ok_or("the fixture has too few keys")?;
    let digest = digests.first().ok_or("the fixture has too few digests")?;
    let group = GroupKeeper::new(
        member_keeper(&fixture)?,
        member_habitat("member", key, digest)?,
        keys.iter().take(3).cloned().collect(),
        digests.clone(),
    );
    assert!(matches!(
        group.sign(b"payload", &SignatureForm::IndexedByPosition, SigningPurpose::Current),
        Err(ManagerError::MemberNotInSigningKeys { .. })
    ));

    // The reference's `params()` returns three fields and its `signers` array is empty.
    assert_eq!(fixture.group.params.keys, ["keys", "mhab", "ndigs"]);
    assert_eq!(fixture.group.params.algo, KeyAlgorithm::Group.as_str());
    assert_eq!(fixture.group.params.signers, 0);
    Ok(())
}

/// A cheap member keeper, whose own keys are not what the group cases are about.
fn member_keeper(fixture: &Fixture) -> Result<Box<dyn IdentifierKeeper>, Box<dyn Error>> {
    let mut keeper = SaltyKeeper::new(
        &passcode_salt(fixture)?,
        SaltySource::Passcode(fixture.provenance.passcode.clone().into()),
        SaltyKeeperConfig {
            transferability: KeyTransferability::Transferable,
            profile: DerivationCost::Ephemeral,
            ..SaltyKeeperConfig::default()
        },
    )?;
    keeper.incept(KeyTransferability::Transferable)?;
    Ok(Box::new(keeper))
}

#[test]
fn the_factory_dispatches_the_way_the_reference_dispatches() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let factory = KeeperFactory::new(passcode_salt(&fixture)?);

    let salty = factory.create(KeeperRequest::Salty(SaltyKeeperRequest {
        transferability: KeyTransferability::Transferable,
        stem: Stem::new("red")?,
        profile: DerivationCost::Ephemeral,
        ..SaltyKeeperRequest::default()
    }))?;
    assert_eq!(salty.algorithm().as_str(), fixture.factory.new_salty_algo);

    let randy = factory.create(KeeperRequest::Randy(RandyKeeperRequest {
        transferability: KeyTransferability::Transferable,
        ..RandyKeeperRequest::default()
    }))?;
    assert_eq!(randy.algorithm().as_str(), fixture.factory.new_randy_algo);

    // Reloading a stored record dispatches the same way.
    assert_eq!(fixture.factory.get_salty_algo, KeyAlgorithm::Salty.as_str());
    assert_eq!(fixture.factory.get_randy_algo, KeyAlgorithm::Randy.as_str());
    assert_eq!(fixture.factory.get_extern_algo, KeyAlgorithm::Extern.as_str());
    assert_eq!(fixture.factory.new_extern_algo, KeyAlgorithm::Extern.as_str());
    Ok(())
}

#[test]
fn everything_the_reference_refuses_is_refused_here() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let factory = KeeperFactory::new(passcode_salt(&fixture)?);

    for rejection in [
        &fixture.factory.unregistered_module,
        &fixture.factory.unregistered_module_get,
        &fixture.factory.unknown_algo,
        &fixture.factory.no_algo,
    ] {
        assert!(!rejection.reference_error_message.is_empty(), "{}", rejection.name);
        assert!(!rejection.note.is_empty(), "{}", rejection.name);
    }

    // An unregistered module, through both of the reference's entry points.
    assert!(
        fixture
            .factory
            .unregistered_module
            .reference_error_message
            .contains("unsupported external module type")
    );
    assert!(matches!(
        factory.create(KeeperRequest::Extern {
            module_type: "mock".to_owned(),
            key_pair_index: 0,
            parameters: serde_json::Map::new(),
        }),
        Err(ManagerError::UnknownExternalModule { .. })
    ));

    // The reference's `Unknown algo` and `No algo specified` are both unrepresentable here: the
    // request enum has four variants and an identifier record names exactly one key manager.
    assert!(
        fixture
            .factory
            .unknown_algo
            .reference_error_message
            .contains("Unknown algo")
    );
    assert!(
        fixture
            .factory
            .no_algo
            .reference_error_message
            .contains("No algo specified")
    );
    assert!(
        serde_json::from_str::<keria_types::api::Hab>(
            r#"{"name":"a","prefix":"E","icp_dt":"2023-12-01T10:05:25.062609+00:00"}"#
        )
        .is_err()
    );
    Ok(())
}

#[test]
fn the_reference_defects_are_recorded_with_their_own_output() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    for quirk in [
        &quirks.randy_discards_its_defaulted_codes,
        &quirks.randy_get_passes_no_next_codes,
        &quirks.salty_rotate_keeps_the_inception_count,
        &quirks.group_params_declares_one_field_and_returns_three,
        &quirks.keeper_publishes_its_private_signers,
        &quirks.every_method_is_async_without_awaiting,
    ] {
        assert_ne!(quirk.note, "");
        assert_ne!(quirk.rust_decision, "");
    }

    // The sealing key depends on the identifier's transferability, so two identifiers under one
    // passcode seal to different keys. Reproduced, and re-derived here rather than copied.
    let aeid = &quirks.salty_aeid_depends_on_transferability;
    assert!(aeid.differ);
    assert_ne!(aeid.note, "");
    assert_ne!(aeid.rust_decision, "");
    let salt = passcode_salt(&fixture)?;
    for (transferable, expected) in [(true, &aeid.transferable_aeid), (false, &aeid.non_transferable_aeid)] {
        let signer = salt.derive_signer_with_profile(
            "",
            transferability(transferable),
            KeyDerivationProfile::Standard(SecurityTier::Low),
        )?;
        assert_eq!(&signer.verifier().qb64()?, expected);
    }
    Ok(())
}
